	/**
	 * 保持するコンテナのListを返します。
	 *
	 * @return コンテナのList
	 */
	public List<MCContainer> getContainers(){
		List<MCContainer> ret = super.getContainers();
		if(!MCCollectionUtil.contains(ret, getCndR())) ret.add(getCndR());
		if(!MCCollectionUtil.contains(ret, getPoL())) ret.add(getPoL());
		if(!MCCollectionUtil.contains(ret, getPodL())) ret.add(getPodL());
		if(!MCCollectionUtil.contains(ret, getArrPurcSchdL())) ret.add(getArrPurcSchdL());
		if(!MCCollectionUtil.contains(ret, getArrActL())) ret.add(getArrActL());
		if(!MCCollectionUtil.contains(ret, getPurcActL())) ret.add(getPurcActL());
		if(!MCCollectionUtil.contains(ret, getDlvInstHdrDataL())) ret.add(getDlvInstHdrDataL());
		if(!MCCollectionUtil.contains(ret, getDlvInstDtlDataL())) ret.add(getDlvInstDtlDataL());
		if(!MCCollectionUtil.contains(ret, getPrmsHdrDataL())) ret.add(getPrmsHdrDataL());
		if(!MCCollectionUtil.contains(ret, getPrmsDtlDataL())) ret.add(getPrmsDtlDataL());
		if(!MCCollectionUtil.contains(ret, getBtnR())) ret.add(getBtnR());
		return ret;
	}

	/**
	 * コンテナに対応したブロックのIDを返します。
	 *
	 * 引数のコンテナに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return ブロックID
	 */
	public String getBlockId(MCContainer aCnt){
		if(aCnt == null) return null;
		if(aCnt == getCndR()) return "Cnd";
		if(aCnt == getPoL()) return "Po";
		if(aCnt == getPodL()) return "Pod";
		if(aCnt == getArrPurcSchdL()) return "ArrPurcSchd";
		if(aCnt == getArrActL()) return "ArrAct";
		if(aCnt == getPurcActL()) return "PurcAct";
		if(aCnt == getDlvInstHdrDataL()) return "DlvInstHdrData";
		if(aCnt == getDlvInstDtlDataL()) return "DlvInstDtlData";
		if(aCnt == getPrmsHdrDataL()) return "PrmsHdrData";
		if(aCnt == getPrmsDtlDataL()) return "PrmsDtlData";
		if(aCnt == getBtnR()) return "Btn";
		return super.getBlockId(aCnt);
	}

	/**
	 * ブロックIDに対応したコンテナを返します。
	 *
	 * 引数のブロックIDに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return コンテナ
	 */
	public MCContainer getContainer(String bId){
		if(bId == null) return null;
		if(bId.equals("Cnd")) return getCndR();
		if(bId.equals("Po")) return getPoL();
		if(bId.equals("Pod")) return getPodL();
		if(bId.equals("ArrPurcSchd")) return getArrPurcSchdL();
		if(bId.equals("ArrAct")) return getArrActL();
		if(bId.equals("PurcAct")) return getPurcActL();
		if(bId.equals("DlvInstHdrData")) return getDlvInstHdrDataL();
		if(bId.equals("DlvInstDtlData")) return getDlvInstDtlDataL();
		if(bId.equals("PrmsHdrData")) return getPrmsHdrDataL();
		if(bId.equals("PrmsDtlData")) return getPrmsDtlDataL();
		if(bId.equals("Btn")) return getBtnR();
		return super.getContainer(bId);
	}

	/**
	 * 保持するPanel(枠)のListを返します。
	 *
	 * @return MCPanelのList
	 */
	public List<MCPanel> getMCPanels(){
		List<MCPanel> ret = super.getMCPanels();
		ret.add(ScreenOpePanel);
		ret.add(CndPanel);
		ret.add(HdrTabPanel);
		ret.add(PoPanel);
		ret.add(PodPanel);
		ret.add(CenterTabPanel);
		ret.add(ArrPurcSchdPanel);
		ret.add(ArrActPanel);
		ret.add(PurcActPanel);
		ret.add(DlvInstPanelPanel);
		ret.add(DlvInstPanelDataPanel);
		ret.add(DlvInstHdrPanelPanel);
		ret.add(DlvInstHdrDataPanel);
		ret.add(DlvInstHdrBtnPanel);
		ret.add(DlvInstDtlPanelPanel);
		ret.add(DlvInstDtlDataPanel);
		ret.add(DlvInstDtlBtnPanel);
		ret.add(PrmsPanelPanel);
		ret.add(PrmsPanelDataPanel);
		ret.add(PrmsHdrPanelPanel);
		ret.add(PrmsHdrDataPanel);
		ret.add(PrmsHdrBtnPanel);
		ret.add(PrmsDtlPanelPanel);
		ret.add(PrmsDtlDataPanel);
		ret.add(PrmsDtlBtnPanel);
		ret.add(BtnPanel);
		return ret;
	}

