	/**
	 * この画面のステータスを設定します。
	 *
	 * @param status ステータス
	 */
	public void setStatus(String status) {
		super.setStatus(status);
		if (UPD_DLVINST.equals(status)) {
			setUPD_DLVINSTStatus();
		}
		else if (UPD_PRMS.equals(status)) {
			setUPD_PRMSStatus();
		}
		else if (SRCH.equals(status)) {
			setSRCHStatus();
		}
		else if (UPD_SCHD.equals(status)) {
			setUPD_SCHDStatus();
		}
		else if (FIX_U.equals(status)) {
			setFIX_UStatus();
		}
		else if (REF.equals(status)) {
			setREFStatus();
		}
	}

