	/**
	 * リストを保持する画面部品のリストを返します。
	 */
	public MCList getList(MCEventBeans combo, MCRow row, MCEventInfo info) {
		MCList list = super.getList(combo, row, info);
		if(list != null) return list;
		if(combo == columnPo_trd_cd) return getPo_trd_cd(row, info);
		if(combo == columnPod_maker_cd) return getPod_maker_cd(row, info);
		if(combo == columnPod_base_unit_cd) return getPod_base_unit_cd(row, info);
		if(combo == columnArrAct_base_unit_cd) return getArrAct_base_unit_cd(row, info);
		if(combo == columnDlvInstDtlData_in_to_loc_cd) return getDlvInstDtlData_in_to_loc_cd(row, info);
		if(combo == columnDlvInstDtlData_trd_unit_cd) return getDlvInstDtlData_trd_unit_cd(row, info);
		if(combo == columnDlvInstDtlData_mfg_inst_no) return getDlvInstDtlData_mfg_inst_no(row, info);
		if(combo == DlvInstDtlData_dlv_p_PPanel.columnDlv_bp_cd) return getDlvInstDtlData_dlv_p_PPanel_columnDlv_bp_cd(row, info);
		if(combo == DlvInstDtlData_tdlv_p_PPanel.columnDlv_bp_cd) return getDlvInstDtlData_tdlv_p_PPanel_columnDlv_bp_cd(row, info);
		if(combo == columnPrmsDtlData_trd_unit_cd) return getPrmsDtlData_trd_unit_cd(row, info);
		if(combo == columnPrmsDtlData_mfg_inst_no) return getPrmsDtlData_mfg_inst_no(row, info);
		return null;
	}

	/**
	 * ActionPerformedイベントが実行されたときに呼び出されます。
	 *
	 * @param ap ActionPerformedイベントが実行されたGUI部品
	 */
	public void doAPEvent(MCAPBeans ap, MCEventInfo info) {
		super.doAPEvent(ap, info);
		if (ap == Cnd_srch) doCnd_srch(info);
		else if (ap == DlvInstHdrBtn_arrSchdCopyAll) doDlvInstHdrBtn_arrSchdCopyAll(info);
		else if (ap == DlvInstHdrBtn_radd) doDlvInstHdrBtn_radd(info);
		else if (ap == DlvInstHdrBtn_rdel) doDlvInstHdrBtn_rdel(info);
		else if (ap == DlvInstHdrBtn_rcopy) doDlvInstHdrBtn_rcopy(info);
		else if (ap == DlvInstDtlBtn_srchDlvInstRecv) doDlvInstDtlBtn_srchDlvInstRecv(info);
		else if (ap == DlvInstDtlBtn_arrSchdCopy) doDlvInstDtlBtn_arrSchdCopy(info);
		else if (ap == DlvInstDtlBtn_radd) doDlvInstDtlBtn_radd(info);
		else if (ap == DlvInstDtlBtn_rdel) doDlvInstDtlBtn_rdel(info);
		else if (ap == DlvInstDtlBtn_rcopy) doDlvInstDtlBtn_rcopy(info);
		else if (ap == PrmsHdrBtn_arrSchdCopyAll) doPrmsHdrBtn_arrSchdCopyAll(info);
		else if (ap == PrmsHdrBtn_radd) doPrmsHdrBtn_radd(info);
		else if (ap == PrmsHdrBtn_rdel) doPrmsHdrBtn_rdel(info);
		else if (ap == PrmsHdrBtn_rcopy) doPrmsHdrBtn_rcopy(info);
		else if (ap == PrmsDtlBtn_arrSchdCopy) doPrmsDtlBtn_arrSchdCopy(info);
		else if (ap == PrmsDtlBtn_radd) doPrmsDtlBtn_radd(info);
		else if (ap == PrmsDtlBtn_rdel) doPrmsDtlBtn_rdel(info);
		else if (ap == PrmsDtlBtn_rcopy) doPrmsDtlBtn_rcopy(info);
		else if (ap == Btn_open_MSBDP0250) doBtn_open_MSBDP0250(info);
		else if (ap == Btn_prnt) doBtn_prnt(info);
		else if (ap == Btn_upd_dlv_inst) doBtn_upd_dlv_inst(info);
		else if (ap == Btn_upd_prms) doBtn_upd_prms(info);
		else if (ap == Btn_upd_purc_arr_schd) doBtn_upd_purc_arr_schd(info);
	}

