	@Override
	public MCCallerPanelBridge createBridge(String id) {
		if (id.equals("MS.MSBDL0120.Srch01")) {
			return new MS_MSBDL0120_Srch01Bridge();
		}
		if (id.equals("MS.MSBDL0120.Srch02")) {
			return new MS_MSBDL0120_Srch02Bridge();
		}
		if (id.equals("MS.MSBDL0120.Upd01")) {
			return new MS_MSBDL0120_Upd01Bridge();
		}
		if (id.equals("MS.MSBDL0120.Upd02")) {
			return new MS_MSBDL0120_Upd02Bridge();
		}
		if (id.equals("MS.MSBDL0120.Upd05")) {
			return new MS_MSBDL0120_Upd05Bridge();
		}
		if (id.equals("MS.MSBDL0120.Prnt01")) {
			return new MS_MSBDL0120_Prnt01Bridge();
		}
		return super.createBridge(id);
	}
